const logo = {
  alt: 'Old Mate Cranes & Rigging',
  url: 'logo01.png',
  width: 240,
  href: 'http://oldmatecranes.com.au/'
};

const menu = {
  link1:{
    copy:'home',
    url: 'http://oldmatecranes.com.au/'
  },
  link2:{
    copy:'about us',
    url:'#aboutus'
  },
  link3:{
    copy:'contact',
    url: '#contact'
  },
  link4:{
    copy:'services',
    url:'#services'
  },
  link5:{
    copy:'safety',
    url: '#safety'
  },
  link6:{
    copy:'industrial',
    url:'#industrial'
  },
  link7:{
    copy:'civil',
    url:'#civil'
  }
};



const Menu = () => {

  const handleItemClick = () => {
    const offcanvas = document.getElementById('offcanvasRight'); // Replace with your offcanvas ID
    const bsOffcanvas = bootstrap.Offcanvas.getInstance(offcanvas);
    bsOffcanvas.hide();
  };


  return (
    <>
      <section>
        <nav className='navbar fixed-top'>
          <div className='container-fluid'>
          <a className='navbar-brand' href={logo.href}>

          <img src={logo.url} alt={logo.alt} width={logo.width} />
          </a>
          <button className='btn btn-light' type='button' data-bs-toggle='offcanvas' data-bs-target='#offcanvasRight' aria-controls='offcanvasRight'><svg width='40px' height='40px' viewBox='0 0 24 24' fill='none' xmlns='http://www.w3.org/2000/svg'><g id='SVGRepo_bgCarrier' strokeWidth='0'/><g id='SVGRepo_tracerCarrier' strokeLinecap='round' strokeLinejoin='round'/><g id='SVGRepo_iconCarrier'> <g clipPath='url(#clip0_429_11066)'> <path d='M3 6.00092H21M3 12.0009H21M3 18.0009H21' stroke='#292929' strokeWidth='2.5' strokeLinecap='round' strokeLinejoin='round'/> </g> <defs> <clipPath id='clip0_429_11066'> <rect width='24' height='24' fill='white' transform='translate(0 0.000915527)'/> </clipPath> </defs> </g></svg></button>
          </div>
        </nav>
        <div className='offcanvas offcanvas-end bg-red' tabIndex='-1' id='offcanvasRight' aria-labelledby='offcanvasRightLabel'>
          <div className='offcanvas-header'>
            <button type='button' className='btn-close' data-bs-dismiss='offcanvas' aria-label='Close'></button>
          </div>
          <div className='offcanvas-body menu-links'>
            <a href={menu.link1.url} data-bs-toggle='offcanvas'>{menu.link1.copy}</a><br/>
            <a href={menu.link2.url} onClick={handleItemClick}>{menu.link2.copy}</a><br/>
            <a href={menu.link3.url} data-bs-toggle='offcanvas'>{menu.link3.copy}</a><br/>
            <a href={menu.link4.url} data-bs-toggle='offcanvas' data-bs-dismiss='offcanvas'>{menu.link4.copy}</a><br/>
            <a href={menu.link5.url}>{menu.link5.copy}</a><br/>
            <a href={menu.link6.url}>{menu.link6.copy}</a><br/>
            <a href={menu.link7.url}>{menu.link7.copy}</a>
          </div>
        </div>
      </section>
    </>
  )
}

export default Menu;
